import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { execSync } from "node:child_process";
import { mkdirSync, writeFileSync, existsSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { cloneOrPull } from "./index.js";

function initBareRepo(dir: string): void {
  mkdirSync(dir, { recursive: true });
  execSync("git init --bare", { cwd: dir, stdio: "pipe" });
}

function makeInitialCommit(workDir: string, bareUrl: string): void {
  mkdirSync(workDir, { recursive: true });
  execSync("git init", { cwd: workDir, stdio: "pipe" });
  execSync(`git -c user.email=t@t.com -c user.name=T remote add origin "${bareUrl}"`, { cwd: workDir, stdio: "pipe" });
  writeFileSync(join(workDir, "README.md"), "hello", "utf-8");
  execSync("git -c user.email=t@t.com -c user.name=T add README.md", { cwd: workDir, stdio: "pipe" });
  execSync("git -c user.email=t@t.com -c user.name=T commit -m 'init'", { cwd: workDir, stdio: "pipe" });
  execSync("git -c user.email=t@t.com -c user.name=T push origin HEAD:main", { cwd: workDir, stdio: "pipe" });
}

describe("cloneOrPull", () => {
  let base: string;
  let bareRepo: string;
  let targetDir: string;
  let sourceWork: string;

  beforeEach(() => {
    base = join(tmpdir(), `clone-test-${Date.now()}`);
    bareRepo = join(base, "bare.git");
    targetDir = join(base, "target");
    sourceWork = join(base, "source");
    initBareRepo(bareRepo);
    makeInitialCommit(sourceWork, bareRepo);
  });

  afterEach(() => {
    rmSync(base, { recursive: true, force: true });
  });

  it("clones a fresh repo when target does not exist", () => {
    cloneOrPull(bareRepo, targetDir, "main", undefined);
    expect(existsSync(join(targetDir, "README.md"))).toBe(true);
    expect(existsSync(join(targetDir, ".git"))).toBe(true);
  });

  it("is idempotent — second call on existing clone does not throw", () => {
    cloneOrPull(bareRepo, targetDir, "main", undefined);
    expect(() => cloneOrPull(bareRepo, targetDir, "main", undefined)).not.toThrow();
  });

  it("checks out the specified branch", () => {
    // push a new branch to the bare repo
    execSync(`git -C "${sourceWork}" -c user.email=t@t.com -c user.name=T checkout -b feature-branch`, { stdio: "pipe" });
    writeFileSync(join(sourceWork, "feature.txt"), "feature content", "utf-8");
    execSync(`git -C "${sourceWork}" -c user.email=t@t.com -c user.name=T add feature.txt`, { stdio: "pipe" });
    execSync(`git -C "${sourceWork}" -c user.email=t@t.com -c user.name=T commit -m 'feat'`, { stdio: "pipe" });
    execSync(`git -C "${sourceWork}" push origin feature-branch`, { stdio: "pipe" });

    cloneOrPull(bareRepo, targetDir, "feature-branch", undefined);
    expect(existsSync(join(targetDir, "feature.txt"))).toBe(true);
  });

  it("creates a new branch when it does not exist on origin", () => {
    cloneOrPull(bareRepo, targetDir, "new-branch", undefined);
    const branch = execSync(`git -C "${targetDir}" branch --show-current`, {
      encoding: "utf-8", stdio: "pipe",
    }).trim();
    expect(branch).toBe("new-branch");
  });

  it("re-clones when target exists but has different origin", () => {
    const anotherBare = join(base, "another.git");
    const anotherWork = join(base, "another-source");
    initBareRepo(anotherBare);
    makeInitialCommit(anotherWork, anotherBare);

    // First: clone from anotherBare into targetDir
    cloneOrPull(anotherBare, targetDir, "main", undefined);
    // Now: clone from bareRepo — should detect URL mismatch and re-clone
    cloneOrPull(bareRepo, targetDir, "main", undefined);

    const originUrl = execSync(`git -C "${targetDir}" remote get-url origin`, {
      encoding: "utf-8", stdio: "pipe",
    }).trim();
    expect(originUrl).toBe(bareRepo);
  });
});

